// Copies shared/sqlite-schema/migrations/*.sql into utils/sqliteMigrations.ts.
// The web Docker build only sees web/, so the shared SQL is embedded here.
// Run `pnpm sync:schema` after changing the shared migrations; a unit test
// fails while the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const webDir = join(dirname(fileURLToPath(import.meta.url)), '..')
const migrationsDir = join(webDir, '..', 'shared', 'sqlite-schema', 'migrations')
const outFile = join(webDir, 'utils', 'sqliteMigrations.ts')

export function buildMigrationsModule() {
  const files = readdirSync(migrationsDir).filter(f => /^v\d+_.*\.sql$/.test(f)).sort()
  const migrations = files.map(file => ({
    version: Number(file.match(/^v(\d+)/)[1]),
    sql: readFileSync(join(migrationsDir, file), 'utf8').replace(/\r\n/g, '\n'),
  }))
  return [
    '// GENERATED by scripts/sync-sqlite-schema.mjs from shared/sqlite-schema/migrations. Do not edit.',
    '',
    'export interface SqliteMigration {',
    '  version: number',
    '  sql: string',
    '}',
    '',
    `export const SQLITE_MIGRATIONS: SqliteMigration[] = ${JSON.stringify(migrations, null, 2)}`,
    '',
  ].join('\n')
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(outFile, buildMigrationsModule())
  console.log(`wrote ${outFile}`)
}
